import type { MeshDb } from '@/lib/mesh/db'
import { deriveNodeId, deriveOriginId } from '@/lib/mesh/protocol'

export interface MeshIdentity {
  nodeId: string
  originId: string
}

/**
 * The installation identifier: a random UUID created once and stored in SQLite.
 *
 * It is generated by the platform CSPRNG (expo-crypto's randomUUID in the app), never
 * derived from the device, the user account, a phone number or an advertising id. Only
 * one-way derivations of it (node id, origin id) ever leave the phone. Clearing the app's
 * data creates a new identity, which is the intended way to "forget" it.
 */
export async function loadIdentity(db: MeshDb, randomUuid: () => string): Promise<MeshIdentity> {
  const read = () => db.first<{ value: string }>("SELECT value FROM mesh_meta WHERE key = 'install_id'")
  let row = await read()
  if (!row) {
    await db.run("INSERT OR IGNORE INTO mesh_meta (key, value) VALUES ('install_id', ?)", [randomUuid()])
    row = await read()
  }
  const installId = row!.value
  return { nodeId: deriveNodeId(installId), originId: deriveOriginId(installId) }
}
